"use client";
// src/tabs.tsx
import { tabs } from "@ui-sdk/core/tabs";
import { createParts } from "./use-primitive.js";
import { createTabsController } from "@ui-sdk/core/tabs";
var parts = createParts(tabs, {
  root: "div",
  list: "div",
  tab: "button",
  "tab-icon": "span",
  indicator: "span",
  panel: "div"
});
var Tabs = parts.Root;
var TabsList = parts.List;
var TabsTab = parts.Tab;
var TabsTabIcon = parts.TabIcon;
var TabsIndicator = parts.Indicator;
var TabsPanel = parts.Panel;
export {
  Tabs,
  TabsIndicator,
  TabsList,
  TabsPanel,
  TabsTab,
  TabsTabIcon,
  createTabsController
};
